window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1458c7d86a90919"]={"versions": [{"id": "FIG-c1458c7d86a90919", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Methoden-Dekompositionsdiagramm der AUTOSAR-Methodologie für die plattformübergreifende Kommunikationsauslegung zwischen Classic Platform und Adaptive Platform. Das Diagramm modelliert die hierarchische Zerlegung einer übergeordneten Entwurfsaktivität in untergeordnete Teilschritte über Kompositionsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordnetes Methodologie-Element: Aktivitäts-/Aufgabenknoten „Design communication between Classic and Adaptive Platform“, dargestellt als abgerundetes Rechteck mit Piktogramm für Work Product / Task.\n</li><li>Untergeordnete Teilschritte: Zwei strukturidentische Aktivitätsknoten (abgeschnittene Beschriftungen im unteren Bildbereich), angebunden über gerichtete Assoziationen mit offener Raute (Shared Aggregation / «nesting») an den übergeordneten Knoten.\n</li><li>Stereotyp / Beziehung: Beide Aggregationsbeziehungen tragen das Stereotyp <code>«nesting»</code>. Kardinalitäten an den Endpunkten sind nicht spezifiziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dekompositionsstruktur eines methodischen Prozessschritts. Der übergeordnete Entwurfsschritt „Design communication between Classic and Adaptive Platform“ kapselt die darunterliegenden Aktivitäten als geschachtelte Teilaufgaben. Ein sequenzieller Kontrollfluss oder Datenfluss ist nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Strukturierungsvorgabe zur methodischen Gliederung der Entwurfsaktivitäten bei der plattformübergreifenden Kommunikation. Da Kardinalitäten fehlen, bleibt die genaue Instanziierungsvorgabe der Unteraktivitäten innerhalb der Aggregation formal unbestimmt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cbf95614f2393385", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Methoden-Dekompositionsdiagramm der AUTOSAR-Methodologie für die plattformübergreifende Kommunikationsauslegung zwischen Classic Platform und Adaptive Platform. Das Diagramm modelliert die hierarchische Zerlegung einer übergeordneten Entwurfsaktivität in untergeordnete Teilschritte über Kompositionsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordnetes Methodologie-Element: Aktivitätsknoten „Design communication between Classic and Adaptive Platform“, symbolisiert durch ein abgerundetes Rechteck mit Task-/Work-Product-Symbolik.\n</li><li>Untergeordnete Teilschritte: Zwei untergeordnete Aktivitätsknoten (Beschriftungen im unteren Bildbereich abgeschnitten).\n</li><li>Beziehungen &amp; Multiplizitäten: Beide Knoten sind über Shared-Aggregation-Kanten mit dem Stereotyp <code>«nesting»</code> an den übergeordneten Knoten angebunden; die Kardinalität an den Zielknoten ist explizit als <code>0..1</code> spezifiziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dekompositionsstruktur eines methodischen Prozessschritts. Der übergeordnete Entwurfsschritt „Design communication between Classic and Adaptive Platform“ kapselt die darunterliegenden Aktivitäten als geschachtelte Teilaufgaben. Ein sequenzieller Kontrollfluss oder Datenfluss ist nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Dekompositionsvorgabe. Die Multiplizität <code>0..1</code> an den Aggregationsenden legt normativ fest, dass die geschachtelten Teilschritte im Rahmen der Gesamtaufgabe jeweils optional sind, aber höchstens einmal instanziiert werden dürfen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-054fe88d3b4185a0", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Methoden-Dekompositionsdiagramm der AUTOSAR-Methodologie für die plattformübergreifende Kommunikationsauslegung zwischen Classic Platform und Adaptive Platform. Das Diagramm modelliert die hierarchische Zerlegung einer übergeordneten Entwurfsaktivität in untergeordnete Teilschritte über Kompositionsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordneter Knoten: „Design communication between Classic and Adaptive Platform“.\n</li><li>Untergeordnete Teilschritte:\n<ul class=\"fig-list\"><li>Linker Knoten: „Design service oriented ...“ (vollständig entfaltete Benennung des serviceorientierten Kommunikationsentwurfs).\n</li><li>Rechter Knoten: „Design signal oriented ...“ (vollständig entfaltete Benennung des signalorientierten Kommunikationsentwurfs).\n</li></ul>\n</li><li>Beziehungen &amp; Multiplizitäten: Beide Unterknoten sind über <code>«nesting»</code>-Aggregationen mit Zielmultiplizität <code>0..1</code> an den übergeordneten Knoten gebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dekompositionsstruktur eines methodischen Prozessschritts. Der übergeordnete Entwurfsschritt „Design communication between Classic and Adaptive Platform“ kapselt die darunterliegenden Aktivitäten als geschachtelte Teilaufgaben. Ein sequenzieller Kontrollfluss oder Datenfluss ist nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Dekompositionsvorgabe. Die Multiplizität <code>0..1</code> an den Aggregationsenden legt normativ fest, dass die geschachtelten Teilschritte im Rahmen der Gesamtaufgabe jeweils optional sind, aber höchstens einmal instanziiert werden dürfen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd4e32cd69fbd172", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Methoden-Dekompositionsdiagramm der AUTOSAR-Methodologie für die plattformübergreifende Kommunikationsauslegung zwischen Classic Platform und Adaptive Platform. Das Diagramm modelliert die hierarchische Zerlegung einer übergeordneten Entwurfsaktivität in untergeordnete Teilschritte über Kompositionsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordneter Knoten: „Design communication between Classic and Adaptive Platform“.\n</li><li>Untergeordnete Teilschritte:\n<ul class=\"fig-list\"><li>Linker Knoten: „Design service oriented ...“ (vollständig entfaltete Benennung des serviceorientierten Kommunikationsentwurfs).\n</li><li>Rechter Knoten: „Design signal oriented ...“ (vollständig entfaltete Benennung des signalorientierten Kommunikationsentwurfs).\n</li></ul>\n</li><li>Beziehungen &amp; Multiplizitäten: Beide Unterknoten sind über <code>«nesting»</code>-Aggregationen mit Zielmultiplizität <code>0..1</code> an den übergeordneten Knoten gebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dekompositionsstruktur eines methodischen Prozessschritts. Der übergeordnete Entwurfsschritt „Design communication between Classic and Adaptive Platform“ kapselt die darunterliegenden Aktivitäten als geschachtelte Teilaufgaben. Ein sequenzieller Kontrollfluss oder Datenfluss ist nicht modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Dekompositionsvorgabe. Die Multiplizität <code>0..1</code> an den Aggregationsenden legt normativ fest, dass die geschachtelten Teilschritte im Rahmen der Gesamtaufgabe jeweils optional sind, aber höchstens einmal instanziiert werden dürfen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c1458c7d86a90919", "to": "FIG-cbf95614f2393385", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>An beiden Aggregationskanten (<code>«nesting»</code>) wird am Zielknoten die Multiplizität <code>0..1</code> ergänzt.\n</li></ul>"}, {"from": "FIG-cbf95614f2393385", "to": "FIG-054fe88d3b4185a0", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Beschriftungen der beiden unteren Aktivitätsknoten werden vollständig sichtbar dargestellt: links „Design service oriented ...“ und rechts „Design signal oriented ...“ (zuvor am rechten Bildrand bzw. Umbruch abgeschnitten).\n</li></ul>"}, {"from": "FIG-054fe88d3b4185a0", "to": "FIG-cd4e32cd69fbd172", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cd4e32cd69fbd172", "to": "FIG-054fe88d3b4185a0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
